/**
 * @file Bundle the actual scanner, parsers, governance and editable native interface from reviewed source.
 * @description Fixed payload inventories and actual bundled-dependency license texts bind each candidate.
 * @remarks Generated bytes are ignored; dirty local candidates are explicit and cannot be hosted releases.
 * @remarks Functions, parameters, state variables and exact declaration locations: generated docs/code-map.md (pnpm code-map).
 */
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import console from 'node:console';
import { createHash, randomBytes } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { build } from 'esbuild';
const require = createRequire(import.meta.url);
const { readRegular, newFile } = require('../desktop/files.cjs');
const { OWNER, PAYLOAD } = require('../desktop/resources.cjs');
const root = path.resolve(import.meta.dirname, '..');
const output = path.resolve(
  process.argv[2] ?? path.join(root, '.runtime/native-resources'),
);
const dirtyAllowed = process.argv[3] === '--allow-dirty';
if (
  !output.startsWith(path.join(root, '.runtime') + path.sep) ||
  fs.existsSync(output) ||
  process.argv.length > 4 ||
  (process.argv[3] && !dirtyAllowed) ||
  (dirtyAllowed && process.env.GITHUB_ACTIONS === 'true')
)
  throw new Error('Choose a fresh owned .runtime output.');
const git = (...args) =>
  execFileSync('git', ['-c', `safe.directory=${root.replaceAll('\\', '/')}`, ...args], {
    cwd: root,
    encoding: 'utf8',
    timeout: 20000,
    maxBuffer: 1024 * 1024,
    windowsHide: true,
  }).trim();
const source = git('rev-parse', 'HEAD'),
  sourceDirty = Boolean(git('status', '--porcelain'));
if (!/^[a-f0-9]{40}$/.test(source) || (sourceDirty && !dirtyAllowed))
  throw new Error('Native source must be clean or an explicit local candidate.');
fs.mkdirSync(output, { recursive: true });
const common = {
  bundle: true,
  platform: 'node',
  target: 'node24',
  format: 'cjs',
  legalComments: 'eof',
  metafile: true,
  alias: { tinyglobby: require.resolve('tinyglobby') },
};
const engine = await build({
  ...common,
  entryPoints: ['src/workbench/worker.ts'],
  outfile: path.join(output, 'worker.cjs'),
});
const api = await build({
  ...common,
  entryPoints: ['src/workbench/native-api.ts'],
  outfile: path.join(output, 'api.cjs'),
});
await build({
  bundle: true,
  platform: 'browser',
  target: 'chrome144',
  entryPoints: ['desktop/ui/app.ts'],
  outfile: path.join(output, 'app.js'),
  legalComments: 'eof',
});
for (const [name, sourceName] of [
  ['index.html', 'index.html'],
  ['style.css', 'style.css'],
])
  fs.copyFileSync(
    path.join(root, 'desktop/ui', sourceName),
    path.join(output, name),
    fs.constants.COPYFILE_EXCL,
  );

// Resolve licenses from every actual external package in the two bundled Node graphs, not a guessed top-level list.
const packages = new Set();
for (const input of [
  ...Object.keys(engine.metafile.inputs),
  ...Object.keys(api.metafile.inputs),
]) {
  if (!input.includes('node_modules/')) continue;
  let directory = path.dirname(fs.realpathSync(path.resolve(root, input)));
  while (
    !fs.existsSync(path.join(directory, 'package.json')) ||
    typeof JSON.parse(readDependency(path.join(directory, 'package.json'))).name !==
      'string'
  ) {
    const parent = path.dirname(directory);
    if (parent === directory) throw new Error('Dependency metadata is absent.');
    directory = parent;
  }
  packages.add(directory);
}
const notices = [];
/** The trusted pnpm store intentionally hardlinks dependency files; bounded descriptor reads here never mutate them. */
function readDependency(file) {
  const descriptor = fs.openSync(
    file,
    fs.constants.O_RDONLY | (fs.constants.O_NONBLOCK ?? 0),
  );
  try {
    const details = fs.fstatSync(descriptor);
    if (!details.isFile() || details.size > 1024 * 1024)
      throw new Error('Dependency notice exceeds its budget.');
    const bytes = Buffer.alloc(details.size + 1);
    let count = 0;
    while (count < bytes.length) {
      const size = fs.readSync(descriptor, bytes, count, bytes.length - count, null);
      if (!size) break;
      count += size;
    }
    if (count !== details.size)
      throw new Error('Dependency notice changed during its read.');
    return bytes.subarray(0, count).toString('utf8');
  } finally {
    fs.closeSync(descriptor);
  }
}
for (const directory of [...packages].sort()) {
  const manifest = JSON.parse(readDependency(path.join(directory, 'package.json')));
  const licenses = fs
    .readdirSync(directory)
    .filter((name) => /^(?:licen[sc]e|copying|notice)(?:[.-].*)?$/iu.test(name));
  if (!licenses.length) {
    // format 0.2.2 carries its copyright/MIT declaration in source rather than a LICENSE file.
    if (
      manifest.name !== 'format' ||
      manifest.version !== '0.2.2' ||
      manifest.licenses?.[0]?.type !== 'MIT'
    )
      throw new Error('Actual bundled dependency lacks a license: ' + manifest.name);
    const original = readDependency(path.join(directory, 'format.js'));
    if (
      !original.startsWith('//\n// format') ||
      !original.includes('Copyright 2010 - 2013 Sami Samhuri') ||
      !original.includes('// MIT License')
    )
      throw new Error('Bundled format license declaration differs.');
    notices.push(
      original.split('\n').slice(0, 10).join('\n') +
        '\n' +
        readRegular(path.join(root, 'LICENSE'), 100000)
          .toString('utf8')
          .split('Permission is hereby granted')[1]
          .replace(/^/, 'Permission is hereby granted'),
    );
  }
  notices.push(
    `\n=== ${manifest.name}@${manifest.version} (${manifest.license ?? 'see text'}) ===\n`,
  );
  for (const name of licenses)
    if (fs.lstatSync(path.join(directory, name)).isFile())
      notices.push(readDependency(path.join(directory, name)));
}
newFile(path.join(output, 'BUNDLED-NOTICES.txt'), notices.join('\n'));
const digest = (file) =>
  createHash('sha256')
    .update(readRegular(file, 16 * 1024 * 1024))
    .digest('hex');
const metadata = {
  schema: 1,
  product: 'documentation-quality-gate',
  version: '1.1.1',
  source,
  sourceDirty,
  files: Object.fromEntries(
    PAYLOAD.map((name) => [name, digest(path.join(output, name))]),
  ),
  owner: Object.fromEntries(
    OWNER.map((name) => [name, digest(path.join(root, 'desktop', name))]),
  ),
};
newFile(path.join(output, 'SOURCE.json'), JSON.stringify(metadata, null, 2) + '\n');
newFile(path.join(output, 'stage-id.txt'), randomBytes(16).toString('hex'));
console.log(
  JSON.stringify({
    staged: true,
    source,
    sourceDirty,
    version: metadata.version,
    dependencies: packages.size,
  }),
);
